/* 仅在本机读取正文；DOCX 使用 ZIP 中的 word/document.xml，不发送文件。 */
window.ScriptImport=(()=>{
async function read(file){if(!file)throw Error('请选择 TXT 或 DOCX 文件。');if(file.size>12*1024*1024)throw Error('本机原型支持12MB以内文本文件，请选择较小的章节文件；现有原文未改变。');const ext=file.name.split('.').pop().toLowerCase();if(ext==='txt'){let bytes=new Uint8Array(await file.arrayBuffer()),text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{text=new TextDecoder('gb18030').decode(bytes);}if(!text.trim())throw Error('文件没有可读正文，请重新选择。');return {text:text.replace(/^\uFEFF/,''),note:'已读取 TXT 全文（UTF-8 / GB18030），未截断。'};}if(ext!=='docx')throw Error('仅支持 TXT / DOCX。旧版 DOC 或 PDF 请先转为 TXT，现有原文未改变。');
const bytes=new Uint8Array(await file.arrayBuffer()),view=new DataView(bytes.buffer);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(view.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('无法识别 DOCX 压缩结构，请重新选择有效的 DOCX。');let at=view.getUint32(end+16,true),total=view.getUint16(end+10,true),entry;for(let n=0;n<total;n++){if(view.getUint32(at,true)!==0x02014b50)throw Error('DOCX 文件目录损坏。');const len=view.getUint16(at+28,true),extra=view.getUint16(at+30,true),comment=view.getUint16(at+32,true),name=new TextDecoder().decode(bytes.slice(at+46,at+46+len));if(name==='word/document.xml'){entry={method:view.getUint16(at+10,true),size:view.getUint32(at+20,true),uncompressed:view.getUint32(at+24,true),offset:view.getUint32(at+42,true)};break;}at+=46+len+extra+comment;}if(!entry)throw Error('DOCX 缺少正文，或是加密文件。请另存为普通 DOCX / TXT。');if(entry.uncompressed>24*1024*1024)throw Error('DOCX 正文过大，请按章节导出 TXT。');const o=entry.offset,start=o+30+view.getUint16(o+26,true)+view.getUint16(o+28,true);let raw=bytes.slice(start,start+entry.size);if(entry.method===8){try{raw=new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());}catch{throw Error('当前浏览器无法解压此 DOCX，请另存为 TXT；未将失败当成成功。');}}else if(entry.method!==0)throw Error('不支持该 DOCX 压缩方式，请另存为 TXT。');const xml=new DOMParser().parseFromString(new TextDecoder().decode(raw),'application/xml');if(xml.querySelector('parsererror'))throw Error('DOCX 正文格式损坏，请重新选择。');const ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main',text=[...xml.getElementsByTagNameNS(ns,'p')].map(p=>[...p.getElementsByTagNameNS(ns,'t')].map(t=>t.textContent).join('')).join('\n');if(!text.trim())throw Error('DOCX 中没有可读文字；扫描图片不支持 OCR，请提供文字版。');return {text,note:'已本机解析 DOCX 正文段落和表格文字；不含页眉页脚、批注、图片 OCR 或原排版。'};
}
return {read};})();
